 d:[["Caddy: Reverse proxy quick-start", "https://caddyserver.com/docs/quick-starts/reverse-proxy", "en"], ["Caddy: Automatic HTTPS", "https://caddyserver.com/docs/automatic-https", "en"], ["Caddy: директива tls (в том числе tls internal)", "https://caddyserver.com/docs/caddyfile/directives/tls", "en"]],
